const { withGradleProperties } = require('expo/config-plugins');

// Android release build tuning, applied to android/gradle.properties.
//
// This has to be a plugin rather than an edit to android/gradle.properties:
// android/ is generated by prebuild, so a hand edit reverts silently the next
// time app.json changes.
//
// ABIs: the Expo default is all four (armeabi-v7a, arm64-v8a, x86, x86_64),
// which carries four copies of every .so. x86/x86_64 only matter for emulators
// and Chromebooks, so they are dropped; armeabi-v7a stays because dropping it
// makes the app uninstallable on 32-bit hardware, which is still a real slice of
// budget Android devices. Play splits the AAB per ABI, so each user downloads
// only their own. For a fast local build on the arm64 test phone, set
// EXPO_ANDROID_ARCHS=arm64-v8a.
const ARCHS = process.env.EXPO_ANDROID_ARCHS || 'armeabi-v7a,arm64-v8a';

// R8 + resource shrinking for release builds. Off by default in Expo's template;
// on here because a store build should ship minified and obfuscated. Keep rules
// in android/app/proguard-rules.pro when a library needs reflection.
const PROPERTIES = {
  reactNativeArchitectures: ARCHS,
  'android.enableMinifyInReleaseBuilds': 'true',
  'android.enableShrinkResourcesInReleaseBuilds': 'true',
  // Play's technical-quality report flags "Resource Shrinking Optimized" as off
  // without this. R8 does the resource shrinking itself rather than a separate
  // pass over the merged resources, which prunes more and drops the intermediate
  // step. The property name is AGP 8.7+; older AGP ignores an unknown one.
  'android.r8.optimizedResourceShrinking': 'true',
};

module.exports = function withAndroidAbi(config) {
  return withGradleProperties(config, (cfg) => {
    const keys = Object.keys(PROPERTIES);
    cfg.modResults = cfg.modResults.filter(
      (item) => !(item.type === 'property' && keys.includes(item.key))
    );
    keys.forEach((key) => {
      cfg.modResults.push({ type: 'property', key, value: PROPERTIES[key] });
    });
    return cfg;
  });
};
